<?php /** @var \App\Models\User $u */
$adm = auth()->user()->isAdmin();
$act = fn ($a) => url('admin/loyalty/members/' . $u->id . '/' . $a);
$ledger = function ($rows, $cash = false) { foreach ($rows as $r) echo '<li><span><b>' . e(\App\Services\Loyalty::TYPES[$r->type] ?? $r->type) . '</b> ' . e($r->reason) . ($r->status !== 'available' ? ' <em class="muted">(' . e($r->status) . ')</em>' : '') . ' <b class="' . ($r->amount < 0 ? 'warn' : 'lime') . '">' . ($r->amount > 0 ? '+' : '') . ($cash ? money($r->amount) : number_format($r->amount)) . '</b></span><small>' . e($r->actor) . ' · ' . e(fmt_date($r->created_at)) . '</small></li>'; if (!count($rows)) echo '<li class="muted">No transactions.</li>'; };
?>
<p><a href="<?= e(url('admin/loyalty/members')) ?>">← All members</a></p>
<div class="kpis">
  <div class="kpi"><b><?= number_format((int) $u->points) ?></b><small>Points <?= $pending ? '(+' . number_format($pending) . ' pending)' : '' ?></small></div><div class="kpi"><b><?= money($u->cashback) ?></b><small>Cashback</small></div>
  <div class="kpi"><b><?= money($u->credit) ?></b><small>Store credit</small></div><div class="kpi"><b><?= e($tier->name ?? '—') ?></b><small>Tier<?= $u->tier_locked ? ' (manually assigned)' : '' ?><?= $u->tier_until ? ' · until ' . e(fmt_date($u->tier_until, false)) : '' ?></small></div>
  <div class="kpi"><b><?= money($metrics['annual']) ?></b><small>Spend (<?= (int) $metrics['months'] ?> mo) · lifetime <?= money($metrics['lifetime']) ?></small></div><div class="kpi"><b><?= (int) $metrics['orders'] ?></b><small>Orders</small></div></div>
<section class="apanel"><h2><?= e($u->name) ?> <span class="pill <?= $u->loyalty_status === 'active' ? 'ok' : '' ?>"><?= e($u->loyalty_status) ?></span></h2>
  <p class="muted"><?= e($u->email) ?> · <?= e($u->phone ?: 'no phone') ?> · ID <code><?= e($u->loyalty_id) ?></code> · referral code <code><?= e($u->referral_code) ?></code> · joined <?= e(fmt_date($u->loyalty_joined_at, false)) ?> · birthday <?= $u->birthday ? e(fmt_date($u->birthday, false)) : '—' ?><?= $u->ambassador ? ' · ★ ambassador ' . (float) $u->ambassador_pct . '%' : '' ?></p>
