<div class="cols"><div class="stack">
  <section class="apanel"><h2>Points ledger</h2><ul class="timeline"><?php $ledger($points); ?></ul></section>
  <section class="apanel"><h2>Cashback ledger</h2><ul class="timeline"><?php $ledger($cash, true); ?></ul></section>
  <section class="apanel"><h2>Store credit (separate wallet)</h2><ul class="timeline"><?php foreach ($credit as $c): ?><li><span><?= e($c->reason) ?> <b class="<?= $c->amount < 0 ? 'warn' : 'lime' ?>"><?= ($c->amount > 0 ? '+' : '−') . money(abs($c->amount)) ?></b></span><small><?= e($c->actor) ?> · <?= e(fmt_date($c->created_at)) ?></small></li><?php endforeach; ?><?php if (!$credit): ?><li class="muted">None.</li><?php endif; ?></ul></section>
  <section class="apanel"><h2>Tier history</h2><ul class="timeline"><?php foreach ($thist as $h): ?><li><span><?= e(\App\Services\LoyaltyTiers::find((int) $h->from_tier)->name ?? '—') ?> → <b><?= e(\App\Services\LoyaltyTiers::find((int) $h->to_tier)->name ?? '—') ?></b> · <?= e($h->reason) ?></span><small><?= e($h->actor) ?> · <?= e(fmt_date($h->created_at)) ?></small></li><?php endforeach; ?></ul></section>
  <section class="apanel"><h2>Rewards, referrals &amp; challenges</h2>
    <h3>Rewards</h3><?php foreach ($reds as $d): ?><p><b><?= e($d->name) ?></b> <code><?= e($d->code) ?></code> <span class="pill"><?= e($d->status) ?></span> <small class="muted"><?= e(fmt_date($d->created_at, false)) ?></small></p><?php endforeach; ?>
    <h3>Referrals</h3><?php foreach ($refs as $d): ?><p><?= e($d->referee) ?> <span class="pill"><?= e($d->status) ?></span></p><?php endforeach; ?>
    <h3>Challenges</h3><?php foreach ($chal as $d): ?><p><?= e($d->name) ?> — <?= (int) $d->progress ?>/<?= (int) $d->target ?> <?= $d->completed_at ? '✓' : '' ?></p><?php endforeach; ?>
    <h3>Purchases</h3><?php foreach ($orders as $o): ?><p><a href="<?= e(url('admin/orders/' . $o->id)) ?>"><?= e($o->number) ?></a> · <?= money($o->total) ?> · <?= e($o->status) ?> · loyalty: <?= e($o->loyalty_state ?: '—') ?></p><?php endforeach; ?></section>
  <section class="apanel"><h2>Audit trail</h2><ul class="timeline"><?php foreach ($audit as $a): ?><li><span><?= e($a->action) ?> <small class="muted"><?= e(mb_substr((string) $a->details, 0, 120)) ?></small></span><small><?= e($a->actor) ?> · <?= e(fmt_date($a->created_at)) ?></small></li><?php endforeach; ?><?php if (!$audit): ?><li class="muted">No admin actions yet.</li><?php endif; ?></ul></section>
</div><div class="stack">
  <section class="apanel"><h2>Adjust points / cashback</h2><form method="post" action="<?= e($act('adjust')) ?>"><?= csrf_field() ?>
    <div class="g2"><?= field_select('wallet', 'Wallet', ['points' => 'Points'] + ($adm ? ['cashback' => 'Cashback'] : []), 'points') ?><?= field_select('dir', 'Action', ['add' => 'Add', 'remove' => 'Deduct'], 'add') ?></div>
    <?= field_text('amount', 'Amount (points, or currency for cashback)', '', ['type' => 'number', 'step' => '0.01', 'min' => '0.01', 'required' => true, 'hint' => $adm ? '' : 'Staff limit: ' . number_format($limit) . ' points']) ?>
    <?= field_text('reason', 'Reason (required, audited)', '', ['required' => true]) ?><button class="btn block" data-confirm="Record this adjustment?">Apply</button></form></section>
  <?php if ($adm): ?>
  <section class="apanel"><h2>Store credit</h2><form method="post" action="<?= e($act('credit')) ?>"><?= csrf_field() ?><div class="g2"><?= field_select('dir', 'Action', ['add' => 'Add', 'remove' => 'Remove'], 'add') ?><?= field_text('amount', 'Amount', '', ['type' => 'number', 'step' => '0.01', 'min' => '0.01', 'required' => true]) ?></div><?= field_text('reason', 'Reason') ?><button class="btn ghost block">Apply</button></form></section>
  <section class="apanel"><h2>Membership tier</h2><form method="post" action="<?= e($act('tier')) ?>"><?= csrf_field() ?><?= field_select('tier_id', 'Assign tier', ['auto' => 'Automatic (calculate)'] + array_column(array_map(fn ($t) => (array) $t, $tiers), 'name', 'id'), $u->tier_locked ? $u->tier_id : 'auto') ?><?= field_text('reason', 'Reason') ?><button class="btn ghost block">Update tier</button></form></section>
  <?php endif; ?>
  <section class="apanel"><h2>Account status</h2><form method="post" action="<?= e($act('status')) ?>"><?= csrf_field() ?><input type="hidden" name="status" value="<?= $u->loyalty_status === 'active' ? 'suspended' : 'active' ?>"><?= field_text('reason', 'Reason') ?><button class="btn <?= $u->loyalty_status === 'active' ? 'ghost danger' : '' ?> block" data-confirm="<?= $u->loyalty_status === 'active' ? 'Suspend this loyalty account? They cannot earn or redeem.' : 'Reactivate this account?' ?>"><?= $u->loyalty_status === 'active' ? 'Suspend loyalty account' : 'Reactivate' ?></button></form></section>
  <section class="apanel"><h2>Issue reward / voucher</h2>
    <form method="post" action="<?= e($act('reward')) ?>"><?= csrf_field() ?><?= field_select('reward_id', 'Reward (free of points)', array_column(array_map(fn ($r) => (array) $r, $rewards), 'name', 'id'), '') ?><button class="btn ghost block">Issue reward</button></form><hr>
    <form method="post" action="<?= e($act('voucher')) ?>"><?= csrf_field() ?><div class="g3"><?= field_select('type', 'Type', ['percent' => '% off', 'fixed' => 'Fixed'], 'percent') ?><?= field_text('value', 'Value', '', ['type' => 'number', 'step' => '0.01', 'min' => '0.01']) ?><?= field_text('days', 'Valid days', '30', ['type' => 'number', 'min' => '1']) ?></div><button class="btn ghost block">Issue voucher</button></form></section>
  <section class="apanel"><h2>Award activity / challenge</h2>
    <form method="post" action="<?= e($act('activity')) ?>"><?= csrf_field() ?><?= field_select('type', 'Activity', array_map(fn ($a) => $a[1], \App\Services\LoyaltyEngagement::ACTIVITIES), 'review') ?><?= field_text('ref', 'Reference (e.g. review id — prevents double awards)') ?><button class="btn ghost block">Award points</button></form><hr>
    <form method="post" action="<?= e($act('challenge')) ?>"><?= csrf_field() ?><?= field_select('challenge_id', 'Challenge', array_column(array_map(fn ($c) => (array) $c, $challenges), 'name', 'id'), '') ?><button class="btn ghost block">Award challenge reward</button></form></section>
  <?php if ($adm): ?><section class="apanel"><h2>Profile &amp; ambassador</h2><form method="post" action="<?= e($act('profile')) ?>"><?= csrf_field() ?><?= field_text('referral_code', 'Custom referral code', $u->referral_code) ?><?= field_text('birthday', 'Birthday', $u->birthday, ['type' => 'date']) ?><?= field_check('ambassador', 'Brand ambassador', (bool) $u->ambassador) ?><?= field_text('ambassador_pct', 'Ambassador commission % (cashback on referrals\' orders)', (float) $u->ambassador_pct, ['type' => 'number', 'step' => '0.1', 'min' => '0', 'max' => '50']) ?><button class="btn ghost block">Save</button></form></section><?php endif; ?>
</div></div>
